let plan;
try { plan = JSON.parse(String(inputs.plan ?? "")); } catch { throw new Error("The campaign plan is invalid. Propose directions again."); }
if (!plan || plan.schemaVersion !== 1 || !plan.brief || !Array.isArray(plan.directions) || plan.directions.length !== 3) throw new Error("The campaign plan does not match schema version 1.");
const choice = String(inputs.choice ?? "").trim().toUpperCase();
if (!["A", "B", "C"].includes(choice)) throw new Error("Direction choice must be A, B, or C.");
const direction = plan.directions.find((item) => item && item.id === choice);
if (!direction) throw new Error(`Direction ${choice} is missing from the captured plan.`);
const brief = plan.brief;
await media.bytes(brief.productImage);
const images = [brief.productImage];
if (brief.referenceRole !== "none") {
  await media.bytes(brief.referenceImage);
  images.push(brief.referenceImage);
}
const optional = brief.referenceRole === "none" ? "No optional reference is assigned." : `Image 2 controls ${brief.referenceRole} only. Use: ${brief.referenceUse || "the assigned role"}. Ignore: ${brief.referenceIgnore || "objects, branding, and identity"}.`;
const prompt = `Create one photorealistic landscape campaign hero at 16:9. Image 1 is the product identity reference: preserve its geometry, proportions, finish, lid, visible branding, and color. ${optional}\n\nSelected direction ${direction.id} — ${direction.title}\nSetting: ${direction.setting}\nComposition: ${direction.composition}\nLighting: ${direction.lighting}\nPalette: ${direction.palette}\nPreserve: ${direction.preservationInstructions}\n\nLeave deliberate copy space for the approved headline and CTA, but do not render, invent, or add any campaign text, logos, labels, or typography.`;
const capturedBrief = { productName: String(brief.productName), campaignMessage: String(brief.campaignMessage), audience: String(brief.audience), headline: String(brief.headline), cta: String(brief.cta), referenceRole: String(brief.referenceRole), referenceUse: String(brief.referenceUse ?? ""), referenceIgnore: String(brief.referenceIgnore ?? "") };
const contract = { schemaVersion: 1, kind: "hero", brief: capturedBrief, selectedDirection: direction, copy: { productName: capturedBrief.productName, headline: capturedBrief.headline, cta: capturedBrief.cta }, sourceOrder: brief.referenceRole === "none" ? ["product identity"] : ["product identity", `optional ${brief.referenceRole} reference`], render: { aspectRatio: "16:9", resolution: "1K", prompt } };
await output("prompt", prompt);
await output("images", images);
await output("contract", JSON.stringify(contract));

if (!inputs.hero || inputs.hero.type !== "image" || (typeof inputs.hero.uri !== "string" && typeof inputs.hero.data !== "string")) throw new Error("The hero model did not return a valid image.");
let contract;
try { contract = JSON.parse(String(inputs.contract ?? "")); } catch { throw new Error("The captured hero contract is invalid."); }
if (!contract || contract.schemaVersion !== 1 || contract.kind !== "hero") throw new Error("The captured hero contract is incomplete.");
await output("hero", inputs.hero);
await output("contract", JSON.stringify(contract));
await output("phase", "hero_ready");
